module sound_compression (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] n,\n    input wire [31:0] I,\n    input wire [31:0] data_in,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] LOAD      = 3'd1;\n    localparam [2:0] SORT      = 3'd2;\n    localparam [2:0] COUNT     = 3'd3;\n    localparam [2:0] CALCULATE = 3'd4;\n    localparam [2:0] SLIDE     = 3'd5;\n    localparam [2:0] DONE_ST   = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [3:0] counter;\n    reg [3:0] write_ptr;\n    reg [31:0] array [0:15];\n    reg [31:0] sorted [0:15];\n    reg [4:0] distinct_count;\n    reg [3:0] freq [0:15];\n    reg [7:0] k_max;\n    reg [4:0] window_size;\n    reg [7:0] max_sum;\n    reg [7:0] current_sum;\n    reg [4:0] window_start;\n    reg [31:0] temp_dividend;\n    reg [15:0] temp_quotient;\n    reg [7:0] sort_counter;\n    integer i;\n\n    // Fixed-point parameter\n    localparam FRAC_BITS = 8;\n    localparam [3:0] MAX_N = 16;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            counter <= 4'd0;\n            write_ptr <= 4'd0;\n            distinct_count <= 5'd0;\n            k_max <= 8'd0;\n            window_size <= 5'd0;\n            max_sum <= 8'd0;\n            current_sum <= 8'd0;\n            window_start <= 5'd0;\n            temp_dividend <= 32'd0;\n            temp_quotient <= 16'd0;\n            sort_counter <= 8'd0;\n            \n            for (i=0; i<16; i=i+1) begin\n                array[i] <= 32'd0;\n                sorted[i] <= 32'd0;\n                freq[i] <= 4'd0;\n            end\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    counter <= 4'd0;\n                    if (start) next_state <= LOAD;\n                end\n                \n                LOAD: begin\n                    if (counter < n && counter < MAX_N) begin\n                        array[counter] <= data_in;\n                        counter <= counter + 4'd1;\n                    end else begin\n                        counter <= 4'd0;\n                        next_state <= SORT;\n                        for (i=0; i<16; i=i+1) sorted[i] <= array[i];\n                    end\n                end\n                \n                SORT: begin\n                    if (sort_counter < n) begin\n                        for (i=0; i<(MAX_N-1); i=i+1) begin\n                            if (sorted[i] > sorted[i+1]) begin\n                                sorted[i] <= sorted[i+1];\n                                sorted[i+1] <= sorted[i];\n                            end\n                        end\n                        sort_counter <= sort_counter + 8'd1;\n                    end else begin\n                        sort_counter <= 8'd0;\n                        next_state <= COUNT;\n                    end\n                end\n                \n                COUNT: begin\n                    if (counter < n) begin\n                        if (counter == 0 || sorted[counter] != sorted[counter-1]) begin\n                            freq[distinct_count] <= 4'd1;\n                            distinct_count <= distinct_count + 5'd1;\n                        end else begin\n                            freq[distinct_count-5'd1] <= freq[distinct_count-5'd1] + 4'd1;\n                        end\n                        counter <= counter + 4'd1;\n                    end else begin\n                        counter <= 4'd0;\n                        temp_dividend <= (I * 8'd8) << FRAC_BITS;\n                        next_state <= CALCULATE;\n                    end\n                end\n                \n                CALCULATE: begin\n                    if (temp_dividend >= (n << FRAC_BITS)) begin\n                        temp_dividend <= temp_dividend - (n << FRAC_BITS);\n                        temp_quotient <= temp_quotient + 16'd1;\n                    end else begin\n                        k_max <= (temp_quotient[15:8] >= 8'd20) ? 8'd16 : temp_quotient[15:8];\n                        window_size <= 5'd1 << temp_quotient[15:8];\n                        next_state <= SLIDE;\n                    end\n                end\n                \n                SLIDE: begin\n                    if (window_start + window_size <= distinct_count) begin\n                        current_sum <= 8'd0;\n                        for (i=0; i < window_size; i=i+1) begin\n                            current_sum <= current_sum + freq[window_start + i];\n                        end\n                        \n                        if (current_sum > max_sum) max_sum <= current_sum;\n                        window_start <= window_start + 5'd1;\n                    end else begin\n                        result <= (k_max >= 8'd20 || window_size >= distinct_count) ? 8'd0 : (n - max_sum);\n                        next_state <= DONE_ST;\n                    end\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                \n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\n    always @(*) begin\n        next_state = state;\n    end\n\nendmodule